INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- devops/openshift/overview ----------
('devops', 'openshift', 'overview', 'What is the single biggest architectural difference between OpenShift Routes and Kubernetes Ingress?', '["They are identical, just named differently", "Routes are HAProxy-based and built into every OCP cluster by default -- vanilla Kubernetes Ingress requires you to install and manage your own Ingress controller", "Ingress is more powerful and supports more TLS modes than Routes", "Routes only work with HTTP, never HTTPS"]', 1, 'This is the first thing most OCP-vs-Kubernetes comparisons lead with: Ingress needs an external controller you choose and manage yourself, while Routes ship as a built-in, HAProxy-backed part of the platform.', 'beginner'),
('devops', 'openshift', 'overview', 'What replaces Kubernetes'' PodSecurityPolicy in OpenShift, and how does its default behavior compare?', '["Nothing -- OCP does not enforce pod security by default", "Security Context Constraints (SCCs) -- OCP''s default SCC (restricted-v2) is stricter than vanilla Kubernetes'' defaults, blocking root by default", "NetworkPolicy objects", "RBAC ClusterRoles"]', 1, 'SCCs are OCP-specific and applied automatically to every pod; the default restricted-v2 SCC blocks running as root, which is stricter than an unconfigured vanilla Kubernetes cluster.', 'beginner'),
('devops', 'openshift', 'overview', 'What is the role of Infrastructure nodes in an OCP cluster, and why do enterprises use them?', '["They are required for the cluster to function at all, same as control plane nodes", "They run platform components (router, registry, monitoring) separately from application workloads, which reduces Red Hat subscription/licensing cost since Infrastructure nodes are typically not counted the same way", "They only exist in single-node OpenShift (SNO) deployments", "They replace the need for worker nodes entirely"]', 1, 'Infrastructure nodes are optional but a common real-world cost-optimization pattern -- separating platform components from app workloads keeps licensing costs down while isolating platform noise from application capacity.', 'intermediate'),
('devops', 'openshift', 'overview', 'What manages OCP cluster version upgrades, and how does that differ from vanilla Kubernetes?', '["Upgrades are always fully manual, same as vanilla Kubernetes", "The Cluster Version Operator (CVO) manages the entire upgrade process automatically once triggered -- vanilla Kubernetes has no equivalent built-in operator and typically requires manual per-component upgrades", "kubeadm upgrade, same tool as vanilla Kubernetes", "Upgrades happen automatically with zero user action required"]', 1, 'CVO is genuinely OCP-specific -- it reads the ClusterVersion object and orchestrates control-plane and worker upgrades in sequence, something vanilla Kubernetes leaves entirely to the operator.', 'intermediate'),
('devops', 'openshift', 'overview', 'Why is DeploymentConfig considered legacy in modern OCP, and what should new work use instead?', '["DeploymentConfig no longer exists in OCP 4.x", "DeploymentConfig is OCP-specific and less portable; standard Kubernetes Deployment objects are the modern default and work identically across any Kubernetes distribution", "DeploymentConfig is faster and should always be preferred", "There is no difference between the two"]', 1, 'DeploymentConfig predates OCP''s alignment with upstream Kubernetes and ties workloads to OCP specifically -- new work should default to Deployment for portability, recognizing DeploymentConfig mainly to work with older codebases.', 'intermediate'),

-- ---------- devops/openshift/fundamentals ----------
('devops', 'openshift', 'fundamentals', 'When must the installation method be UPI (User Provisioned Infrastructure) instead of IPI?', '["UPI is always preferred regardless of environment", "UPI is required when OCP cannot provision the underlying infrastructure itself -- bare-metal, on-prem, or restricted/disconnected networks", "UPI is only for AWS installs", "IPI and UPI are the same thing with different names"]', 1, 'IPI has OCP''s installer create and manage the cloud infrastructure itself (AWS/Azure/GCP/vSphere); UPI is required wherever that automatic provisioning isn''t possible, most commonly bare-metal or restricted networks.', 'beginner'),
('devops', 'openshift', 'fundamentals', 'In an OCP install-config.yaml, why must controlPlane.replicas always be an odd number, specifically 3, and never 2?', '["3 is just a Red Hat convention with no technical reason", "etcd (which runs on control plane nodes) requires a quorum to keep functioning during a node failure -- 2 nodes cannot achieve quorum if one fails, but 3 can tolerate one failure and still have a majority", "2 control plane nodes are technically fine but unsupported by Red Hat", "It is only 3 for cost reasons, not technical ones"]', 1, 'etcd is a quorum-based distributed store -- with 2 members, losing 1 leaves no majority and the cluster stops accepting writes; 3 members tolerate 1 failure while keeping a 2-out-of-3 majority.', 'intermediate'),
('devops', 'openshift', 'fundamentals', 'What is a Project in OpenShift, in relation to a Kubernetes Namespace?', '["An entirely separate, unrelated concept from Namespaces", "A Kubernetes Namespace with additional OCP metadata (display-name, description, requester annotations) layered on top", "A Project spans multiple clusters, unlike a Namespace", "Projects are deprecated in OCP 4.x in favor of Namespaces"]', 1, 'A Project is not a different resource -- it IS a Namespace underneath, with extra OCP-specific annotations like openshift.io/display-name and openshift.io/requester added automatically.', 'beginner'),
('devops', 'openshift', 'fundamentals', 'What must NOT overlap when planning OCP cluster networking (Machine, Cluster, and Service networks)?', '["Nothing -- all three networks can safely overlap", "All three CIDR ranges (node IPs, pod network, service network) must be non-overlapping, or routing and connectivity break in ways that are hard to diagnose after install", "Only the Machine and Service networks need to be distinct; Cluster network can overlap either", "This only matters for UPI installs, not IPI"]', 1, 'Overlapping CIDRs is a classic pre-install planning mistake -- once the cluster network is set at install time it is very disruptive to change, so getting this right up front matters.', 'intermediate'),
('devops', 'openshift', 'fundamentals', 'What is the practical difference between oc rollout undo deployment/myapp and oc rollout undo deployment/myapp --to-revision=2?', '["They are identical commands", "The first rolls back to the immediately previous revision; --to-revision=2 rolls back to a specific numbered revision from rollout history, which may not be the most recent prior one", "--to-revision only works on DeploymentConfig, never Deployment", "The first command deletes the deployment entirely"]', 1, 'oc rollout history shows numbered revisions -- without --to-revision you get the immediately prior one, but a specific --to-revision lets you jump back further if the most recent rollback target isn''t the one you actually want.', 'intermediate'),

-- ---------- devops/openshift/intermediate ----------
('devops', 'openshift', 'intermediate', 'Why does etcd have such a strict disk latency requirement (p99 fsync under 10ms), and what happens if storage is too slow?', '["It has no real latency requirement, that is just a recommendation", "etcd fsyncs to disk on every write to guarantee durability -- slow disk I/O directly slows down every API server write, which in turn slows the entire cluster''s responsiveness", "Disk latency only affects etcd backups, not live cluster operations", "etcd does not use local disk at all, only memory"]', 1, 'Every write to the cluster (a new pod, a config change) goes through etcd, which fsyncs for durability before acknowledging -- if the underlying disk is slow, that latency is felt on every single cluster write, not just etcd itself.', 'advanced'),
('devops', 'openshift', 'intermediate', 'Why should worker MachineConfigPools be paused before applying multiple MachineConfig changes?', '["Pausing is required by OCP and cannot be skipped", "Without pausing, each MachineConfig change triggers its own separate rolling reboot of affected nodes -- pausing lets you batch multiple changes into a single reboot cycle instead of one per change", "Pausing prevents the changes from ever being applied", "Pausing only affects control plane nodes, not workers"]', 1, 'Each MachineConfig applied while unpaused triggers its own drain-and-reboot cycle on affected nodes -- pausing the MCP, applying several MachineConfigs, then unpausing collapses that into one rolling reboot instead of several.', 'advanced'),
('devops', 'openshift', 'intermediate', 'What container runtime does OCP use, and what CLI is used to inspect it directly on a node?', '["Docker, inspected with the docker CLI", "CRI-O, inspected on the node with crictl (e.g. crictl ps, crictl logs)", "containerd, inspected with ctr", "OCP has no container runtime, kubelet runs containers directly"]', 1, 'kubelet talks to CRI-O via the Container Runtime Interface; when you need to go below oc/kubectl to debug at the container-runtime level, crictl (run via SSH on the node) is the tool, not the docker CLI.', 'intermediate'),
('devops', 'openshift', 'intermediate', 'Reading `oc describe pod <pending-pod>`, the Events show "0/3 nodes available: 3 Insufficient memory". What does this tell you, and what should you check next?', '["The pod YAML has a syntax error", "No node in the cluster currently has enough allocatable memory to satisfy the pod''s resource requests -- check oc adm top nodes and the pod''s resources.requests.memory value", "The image failed to pull", "The Service has no matching selector"]', 1, 'Scheduler event messages directly name the reason a pod can''t be placed -- here it is a resource-capacity problem, not an image, config, or networking issue, so the fix is either lowering requests or adding capacity.', 'intermediate'),
('devops', 'openshift', 'intermediate', 'What does Cluster Operators (`oc get co`) showing AVAILABLE=True, PROGRESSING=False, DEGRADED=False across every operator actually confirm?', '["Every application workload on the cluster is healthy", "Every OCP platform component itself is healthy and stable -- this is a platform health check, not an application health check", "The cluster has finished a version upgrade", "All pods across all namespaces are Running"]', 1, 'Cluster Operators track platform components (API server, ingress, monitoring, etcd, etc.) -- a clean `oc get co` means the platform is healthy, but says nothing about whether your own application pods are actually working correctly.', 'intermediate'),

-- ---------- devops/openshift/advanced ----------
('devops', 'openshift', 'advanced', 'What is the correct upgrade path from OCP 4.12 to OCP 4.14, and why does it matter?', '["Upgrade directly from 4.12 to 4.14 in one step, always", "Upgrade sequentially through 4.13 first (4.12 -> 4.13 -> 4.14), unless both versions are on the same EUS (Extended Update Support) track, which permits skipping the odd version between them", "Version numbers do not matter, any upgrade path works", "Downgrade to 4.11 first, then upgrade to 4.14"]', 1, 'Sequential minor-version upgrades are the default rule; EUS channels (even versions only, like 4.12 and 4.14) are the specific, supported exception that allows skipping the odd version in between.', 'advanced'),
('devops', 'openshift', 'advanced', 'For OpenShift Virtualization, why does live migration of a VM require RWX (ReadWriteMany) storage specifically, not RWO?', '["RWX is simply faster than RWO for all workloads", "Live migration needs the VM''s disk accessible from both the source and destination node AT THE SAME TIME during the transfer -- RWO only allows one node to mount the volume at a time, which breaks that requirement", "RWO storage does not support VMs at all", "RWX is required by Red Hat licensing, not a technical constraint"]', 1, 'During a live migration the VM is still running on the source node while the destination node needs to start reading the same disk -- that simultaneous multi-node access is exactly what RWX provides and RWO explicitly does not.', 'advanced'),
('devops', 'openshift', 'advanced', 'In a Tekton Pipeline, what is the relationship between a Task and a TaskRun, and Pipeline and PipelineRun?', '["Task and Pipeline are executions; TaskRun and PipelineRun are their static definitions", "Task and Pipeline are the reusable, static definitions of work; TaskRun and PipelineRun represent one actual execution of them", "There is no meaningful difference, the names are interchangeable", "TaskRun and PipelineRun are only used for debugging, not real execution"]', 1, 'This mirrors Kubernetes'' Job/Pod-style pattern: Task/Pipeline define what should happen, while TaskRun/PipelineRun are the concrete, one-time records of an actual execution with its own status and logs.', 'intermediate'),
('devops', 'openshift', 'advanced', 'Why is Manual (not Automatic) the recommended OLM Subscription approval strategy for production Operators?', '["Manual approval is required by OCP and cannot be changed", "Automatic approval lets an upstream Operator upgrade apply itself on the vendor''s schedule, not yours -- Manual approval means someone reviews and approves each upgrade before it touches production", "Manual approval is faster than Automatic", "There is no functional difference between the two settings"]', 1, 'Automatic approval means a new Operator version in its subscribed channel gets applied without human review -- fine for a dev cluster, risky for production where you want to control exactly when an upgrade lands.', 'advanced'),
('devops', 'openshift', 'advanced', 'What does `oc adm must-gather` actually collect, and when should it be run?', '["Only the logs of the pod you specify", "A full diagnostic bundle -- pod logs across all namespaces, cluster operator status, recent events, node configs/conditions, and etcd member status -- typically run before opening a Red Hat support case", "It only works if the cluster is already down", "It automatically fixes any detected issues"]', 1, 'must-gather is a comprehensive, cluster-wide snapshot meant to hand to Red Hat support (or use yourself) -- it is diagnostic-only, collecting evidence rather than taking any corrective action.', 'intermediate'),

-- ---------- devops/openshift/certification ----------
('devops', 'openshift', 'certification', 'On the EX280 exam, what command prefix is specifically associated with RBAC and SCC administration tasks?', '["oc get", "oc adm policy", "oc create", "oc expose"]', 1, 'oc adm policy covers both role bindings (add-role-to-user, add-cluster-role-to-user) and SCC grants (add-scc-to-user, add-scc-to-group) -- it is the single most OpenShift-specific command family tested on EX280.', 'intermediate'),
('devops', 'openshift', 'certification', 'Which SCCs are, from least to most privileged, correctly ordered per the certification guide''s reference list?', '["privileged -> anyuid -> restricted-v2", "restricted-v2 -> restricted -> nonroot -> anyuid -> hostmount-anyuid -> privileged", "anyuid -> restricted -> privileged -> restricted-v2", "There is no defined ordering between SCCs"]', 1, 'restricted-v2 (OCP 4.11+ default) is the most restrictive, escalating through restricted, nonroot, and anyuid, up to hostmount-anyuid and finally privileged, which grants full host-level access.', 'advanced'),
('devops', 'openshift', 'certification', 'What are the three Route TLS termination modes tested on EX280, and how do they differ in where TLS ends?', '["basic, advanced, custom -- these are not real Route modes", "edge (TLS ends at the router, plain HTTP to the pod), passthrough (TLS goes all the way to the pod, router cannot inspect it), reencrypt (TLS to the router, then a new cert to the pod)", "All three modes terminate TLS at the pod, they only differ in cert format", "edge and passthrough are identical; reencrypt is deprecated"]', 1, 'This distinction is one of the most commonly tested OCP-specific networking concepts -- edge trades pod-level encryption for router-level visibility, passthrough keeps end-to-end encryption but hides traffic from the router, and reencrypt does both by re-encrypting after inspection.', 'intermediate'),
('devops', 'openshift', 'certification', 'What is the difference between EX280, EX288, and EX380?', '["They are the same exam offered in three regions", "EX280 (Administration), EX288 (Application Development), and EX380 (Automation, using Ansible) are three distinct Red Hat OpenShift certifications with different focus areas", "EX280 is a prerequisite that must be passed before taking EX288 or EX380", "Only EX280 is a real, current certification; the others are retired"]', 1, 'Each targets a different role: EX280 for cluster/platform administration, EX288 for developers building and deploying apps on OCP, and EX380 for Ansible-driven OCP automation.', 'intermediate'),
('devops', 'openshift', 'certification', 'Why are all Red Hat OpenShift certification exams performance-based rather than multiple choice?', '["Because multiple-choice exams are cheaper to administer", "They test whether a candidate can actually perform real tasks (deploy, expose, secure, troubleshoot) on a live OpenShift cluster within a time limit, not whether they can recognize a correct answer among options", "Performance-based exams are easier to pass than multiple choice", "This is unique to EX280 only, not EX288 or EX380"]', 1, 'Every Red Hat exam in this family puts the candidate on a real cluster with real tasks to complete -- this is deliberate, since the skill being certified is hands-on cluster administration, not recall.', 'beginner'),

-- ---------- devops/openshift/projects ----------
('devops', 'openshift', 'projects', 'In the multi-environment Routes/SCC/quota project, why is it useful to intentionally trigger an SCC violation rather than only building the happy path?', '["It is not useful -- production projects should avoid all errors", "Interviewers and real production work both care whether you have actually diagnosed and fixed an SCC error, not just whether your app happens to run under default settings", "SCC violations cannot be intentionally triggered in OpenShift", "Triggering errors on purpose is against Red Hat''s terms of use"]', 1, 'The project explicitly calls for documenting the real error message and the exact oc adm policy command used to fix it -- demonstrating diagnosis, not just a working end state, is what makes a portfolio project interview-worthy.', 'intermediate'),
('devops', 'openshift', 'projects', 'What is the practical difference between deploying with S2I (`oc new-app <git-url>`) and building a Tekton Pipeline around the same source repo?', '["They accomplish the same thing and there is no reason to do both", "S2I gives OCP-managed BuildConfig/ImageStream automation directly from source with minimal setup; a Tekton Pipeline adds explicit, inspectable stages (clone/build/deploy) and event-driven triggers for a repeatable CI/CD workflow", "Tekton can only deploy pre-built images, never build from source", "S2I is deprecated and Tekton is its only replacement"]', 1, 'S2I is the fastest path from source to running app with almost no configuration; Tekton trades that simplicity for explicit, versioned pipeline stages and webhook-driven automation -- the project has you build both to feel that tradeoff directly.', 'intermediate'),

-- ---------- devops/openshift/roadmap ----------
('devops', 'openshift', 'roadmap', 'Per the roadmap, why is it recommended to be solid on core Kubernetes before starting OpenShift specifically?', '["OpenShift has nothing in common with Kubernetes, so prior K8s knowledge is irrelevant", "OCP assumes Kubernetes fundamentals (Pods, Deployments, Services, kubectl) as a given and layers OCP-specific features on top -- learning both simultaneously makes it hard to tell which concept belongs to which layer", "Kubernetes knowledge is only useful for the certification exam, not daily work", "OpenShift requires unlearning Kubernetes concepts entirely"]', 1, 'The roadmap is explicit that trying to learn Kubernetes and OpenShift at the same time slows progress on both -- OCP-specific features (Routes, SCCs, Operators) only make sense once the underlying Kubernetes model is already familiar.', 'beginner'),
('devops', 'openshift', 'roadmap', 'Which two hands-on actions does the roadmap specifically call out as things you should practice even though they feel risky, rather than avoiding them?', '["Deleting a production namespace and restoring from a laptop backup", "Running an actual cluster upgrade and taking/restoring an etcd backup, both on a disposable test cluster where it is safe to break things", "Granting the privileged SCC to every ServiceAccount by default", "Disabling all Cluster Operators to see what happens"]', 1, 'The roadmap explicitly flags "never running an actual upgrade or backup because it feels risky" as a red flag to avoid -- both should be practiced deliberately on a disposable cluster before they are ever needed for real.', 'intermediate'),

-- ---------- devops/python/overview ----------
('devops', 'python', 'overview', 'Why is Python generally preferred over Bash once automation logic gets complex (error handling, retries, structured data)?', '["Bash cannot run on Linux servers", "Python has built-in try/except error handling, native JSON/YAML parsing, and testable, reusable modules -- Bash gets unreadable fast once logic goes beyond simple sequential shell commands", "Python scripts always run faster than Bash scripts", "Bash cannot call REST APIs at all"]', 1, 'The rule of thumb given is: Bash for simple file/shell operations under ~20 lines, Python once you need real error handling, structured data parsing, or reusability -- not a blanket "Python is always better" claim.', 'beginner'),
('devops', 'python', 'overview', 'Why are dictionaries described as the most important data type for DevOps Python scripting specifically?', '["Dictionaries are faster than lists for every operation", "JSON responses from Kubernetes, AWS, and Azure APIs map directly onto Python dictionaries, so comfortably traversing and building nested dicts is a core, everyday DevOps skill", "Dictionaries are the only mutable data type in Python", "DevOps scripts never need ordered data, only key-value data"]', 1, 'Since so much of DevOps automation is calling cloud/Kubernetes REST APIs and getting JSON back, dict comprehension and nested-dict traversal show up constantly -- more than in general-purpose Python work.', 'beginner'),
('devops', 'python', 'overview', 'What is the recommended way to manage multiple Python versions on one machine for DevOps work?', '["Manually edit the system Python binary", "Use pyenv to install and switch between Python versions cleanly, combined with venv for per-project virtual environments", "Always use the OS-default system Python for every project", "Reinstall the OS whenever a different Python version is needed"]', 1, 'pyenv handles multiple interpreter versions side by side; a virtual environment (python3 -m venv) then isolates per-project dependencies on top of whichever interpreter version is active -- the two solve different problems and are normally used together.', 'intermediate'),

-- ---------- devops/python/fundamentals ----------
('devops', 'python', 'fundamentals', 'What is the difference between a Python list and a tuple, and when should each be used?', '["They are functionally identical, tuples just use different bracket syntax", "Lists are mutable (can be modified after creation) and best for data that changes; tuples are immutable and best for fixed data like coordinates or fixed-format records", "Tuples can hold more data types than lists", "Lists cannot be nested, only tuples can"]', 1, 'The immutability of a tuple is the whole point -- using one signals "this data should not change," which is useful for things like a fixed (x, y) coordinate or a database row shape.', 'beginner'),
('devops', 'python', 'fundamentals', 'Given `s = "Hello World"`, what does `s[::-1]` produce, and why?', '["An error, since strings do not support negative step slicing", "\"dlroW olleH\" -- a step of -1 walks the string backwards from the end to the start", "\"Hello World\" unchanged, -1 is ignored", "Only the last character, \"d\""]', 1, 'Slice syntax is [start:stop:step] -- omitting start and stop while using step -1 walks the entire string from the last index to the first, reversing it.', 'beginner'),
('devops', 'python', 'fundamentals', 'What is the key difference between `os.system()` and the `subprocess` module for running shell commands from Python?', '["os.system() is the modern, recommended approach", "os.system() only returns the exit code with no way to capture output; subprocess (subprocess.run) gives full control -- capturing stdout/stderr, setting env vars, and streaming output", "subprocess cannot capture stderr, only os.system() can", "They are functionally identical, subprocess is just newer syntax"]', 1, 'subprocess.run() is the modern standard specifically because os.system() gives you almost nothing back except an exit code -- no captured output, no fine-grained control over the child process.', 'intermediate'),
('devops', 'python', 'fundamentals', 'In Python OOP, what is the practical effect of a double-underscore-prefixed attribute like `self.__value`?', '["It is a syntax error", "Name mangling -- Python internally renames it to _ClassName__value, making accidental access/override from subclasses much less likely (though not truly private)", "It makes the attribute a class variable shared across all instances", "It has no effect, single and double underscore prefixes are identical"]', 1, 'Double-underscore name mangling is Python''s closest equivalent to strongly private attributes -- it is a convention enforced by a real mechanism (renaming), not just a naming style, though it can still technically be accessed via the mangled name.', 'intermediate'),
('devops', 'python', 'fundamentals', 'Why must default arguments always come after non-default arguments in a Python function definition?', '["This is just a style preference, either order works", "Python resolves positional arguments left to right -- if a default-valued parameter came before a required one, Python could not unambiguously determine which values map to which parameter when called positionally", "Default arguments are evaluated in reverse order", "This rule only applies to keyword-only functions"]', 1, 'def wish(name="Guest", msg) is invalid syntax specifically because of this left-to-right positional resolution -- msg would have no way to receive a value if name uses its default.', 'intermediate'),

-- ---------- devops/python/intermediate ----------
('devops', 'python', 'intermediate', 'When paginating through AWS API results with boto3 (e.g. listing EC2 instances), why use a paginator instead of calling describe_instances directly in a loop?', '["Paginators are purely optional convenience code with no functional benefit", "AWS APIs cap the number of results per call and return a continuation token -- a paginator (get_paginator) automatically handles fetching every page for you instead of you manually tracking and passing that token", "describe_instances always returns every result in a single call regardless of count", "Paginators are required only for S3, never for EC2"]', 1, 'Without a paginator, a script that only calls describe_instances once will silently miss results beyond the first page in an account with many instances -- the paginator loop in the reference code handles this correctly.', 'intermediate'),
('devops', 'python', 'intermediate', 'In the Kubernetes Python client, what is the purpose of trying `config.load_incluster_config()` before falling back to `config.load_kube_config()`?', '["load_incluster_config always fails and exists only for testing", "It lets the same script work both when running inside a cluster as a Pod (using the Pod''s mounted service account) and when running locally against a kubeconfig file, without hardcoding which environment it is in", "load_kube_config is deprecated and should never be used", "The two functions do exactly the same thing"]', 1, 'This try/except pattern is the standard way to write a Kubernetes automation script that works unmodified whether it runs as a CronJob inside the cluster or from a developer''s laptop.', 'advanced'),
('devops', 'python', 'intermediate', 'Why does the AWS automation example call `client.exceptions.ResourceNotFoundException` and `NoCredentialsError` as separate, specific except blocks instead of one bare `except Exception`?', '["Bare except blocks are actually faster to execute", "Catching specific exceptions lets the script respond differently to each failure mode (log-and-raise for a missing secret, sys.exit(1) for missing credentials) instead of treating every possible failure identically", "Python does not allow multiple except blocks in one try", "boto3 only raises one type of exception, so this is unnecessary"]', 1, 'A missing secret and missing AWS credentials call for genuinely different responses -- specific exception handling is what makes that possible; a single bare except would treat both the same way and lose that distinction.', 'intermediate'),

-- ---------- devops/python/interview ----------
('devops', 'python', 'interview', 'When reading YAML in Python, why use `yaml.safe_load()` instead of `yaml.load()`?', '["safe_load is faster to execute", "yaml.load() without a Loader argument can execute arbitrary Python objects embedded in the YAML, which is a code-execution risk; safe_load() restricts parsing to basic, safe data types", "safe_load supports more YAML features than load", "There is no real difference, safe_load is just newer syntax"]', 1, 'This is a real, commonly-tested security distinction -- plain yaml.load() can be tricked into instantiating arbitrary Python objects from untrusted YAML input, which safe_load() specifically prevents.', 'intermediate'),
('devops', 'python', 'interview', 'In the multi-service health-check example, why use `concurrent.futures.ThreadPoolExecutor` instead of checking each service sequentially in a for loop?', '["ThreadPoolExecutor is required for any use of the requests library", "Checking services sequentially means total time is the sum of every service''s response time; checking them concurrently means total time is roughly the slowest single service''s response time", "Sequential checks are not possible in Python", "ThreadPoolExecutor guarantees a faster response from each individual service"]', 1, 'Since each health check is I/O-bound (waiting on a network response), running them concurrently via a thread pool means the script waits for the slowest one, not the sum of all of them.', 'intermediate'),
('devops', 'python', 'interview', 'What does `check=True` do when calling `subprocess.run()`, and why does automation code often set it?', '["It prints the command before running it", "It raises a CalledProcessError automatically if the command exits with a non-zero exit code, so a failing command doesn''t silently continue as if it had succeeded", "It runs the command twice to confirm the result", "It suppresses all output from the command"]', 1, 'Without check=True, subprocess.run() returns normally even if the underlying command failed -- check=True converts that into an explicit exception, which is usually what you want in an automation script.', 'intermediate'),

-- ---------- devops/shell-scripting/overview ----------
('devops', 'shell-scripting', 'overview', 'What do the three flags in `set -euo pipefail` each do?', '["-e enables verbose mode, -u enables Unicode, -o enables options mode", "-e exits on any command failure, -u errors on unset variables, pipefail makes a pipeline fail if ANY stage fails (not just the last)", "All three flags do the same thing and are redundant together", "-e, -u, and pipefail only affect interactive shells, not scripts"]', 1, 'Without pipefail specifically, `false | true` returns exit code 0 (the last command''s status) even though the first command in the pipe failed -- pipefail closes that gap, which -e alone does not catch.', 'beginner'),
('devops', 'shell-scripting', 'overview', 'Why is `"$var"` (double-quoted) considered essential, while `$var` (unquoted) is a common source of real bugs?', '["Quoting only affects readability, not behavior", "An unquoted variable undergoes word-splitting and glob expansion, which breaks on values containing spaces or special characters; quoting preserves the value exactly as one token", "Double quotes make a variable read-only", "Unquoted variables run faster than quoted ones"]', 1, 'This is one of the most common real-world bash bugs -- a filename or path containing a space silently breaks into multiple arguments when the variable holding it is unquoted.', 'beginner'),
('devops', 'shell-scripting', 'overview', 'What is the correct, safe pattern for reading a file line by line in bash, and what does each part of it do?', '["for line in $(cat file); do ... done -- always safe for any file", "while IFS= read -r line; do ... done < file -- IFS= preserves leading/trailing whitespace, -r prevents backslash escapes from being interpreted", "cat file | while read line; do ... done -- functionally identical to the IFS/-r version", "grep . file | xargs echo -- the standard way to read files line by line"]', 1, 'The `for line in $(cat file)` pattern splits on whitespace, breaking on lines with spaces; `while IFS= read -r` is the pattern that correctly handles arbitrary line content including leading whitespace and backslashes.', 'intermediate'),
('devops', 'shell-scripting', 'overview', 'Why does `<(command)` process substitution avoid the "subshell problem" that piping into a while loop has?', '["Process substitution does not actually run in bash", "Piping into a while loop runs the loop in a subshell, so variables set inside the loop are lost once the pipe finishes; process substitution with < <(command) keeps the loop in the current shell, so variable changes persist", "The subshell problem only affects for loops, never while loops", "There is no functional difference, process substitution is only for style"]', 1, 'This is a well-known bash gotcha: `command | while read ...` runs the while loop in a subshell (because it is the right side of a pipe), so any variables it modifies do not survive past the loop -- process substitution sidesteps this entirely.', 'advanced'),
('devops', 'shell-scripting', 'overview', 'What is the difference between `command 2>&1 > file` and `command > file 2>&1`, and why does the order matter?', '["They are identical, redirection order never matters", "command > file 2>&1 sends both stdout and stderr to file (correct); command 2>&1 > file sends stderr to wherever stdout was pointing BEFORE the redirect (usually the terminal), then only stdout goes to file", "2>&1 always overrides any later redirection regardless of order", "Neither form actually redirects stderr in bash"]', 1, 'Redirections are processed left to right -- `2>&1 > file` duplicates stderr to the CURRENT stdout target (the terminal) before stdout is then redirected to file, so stderr keeps going to the terminal instead of the file. This exact ordering gotcha is a common real-world mistake.', 'advanced')

